-- ============================================
-- LUMA — Thème 4 : MOYEN 2/3 x4 — Demander un changement de siège et discuter avec son voisin
-- ============================================


update scenarios set content = '{"characters": {"flight_attendant": "l''hôtesse de l''air", "neighbor": "le voisin de siège"}, "start_node": "n1", "nodes": {"n1": {"speaker": "flight_attendant", "text": "Welcome aboard! Can I help you find your seat?", "text_fr": "Bienvenue à bord ! Je peux vous aider à trouver votre siège ?", "choices": [{"text": "Actually, I was hoping to switch seats — is there anything available?", "text_fr": "En fait, j''espérais changer de siège — il y a quelque chose de disponible ?", "next": "n2"}, {"text": "I''m all set, thank you, just heading to my seat.", "text_fr": "Je suis bon, merci, je vais juste à mon siège.", "next": "n2b"}]}, "n2": {"speaker": "flight_attendant", "text": "Let me check — there''s an aisle seat a few rows back, would that work?", "text_fr": "Laissez-moi vérifier — il y a un siège côté couloir quelques rangs plus loin, ça irait ?", "choices": [{"text": "Perfect, an aisle seat would actually be great, thank you.", "text_fr": "Parfait, un siège couloir serait super en fait, merci.", "next": "n3"}, {"text": "Actually, I was hoping for a window seat if possible.", "text_fr": "En fait, j''espérais un siège hublot si possible.", "next": "n2c"}]}, "n2b": {"speaker": "you_thought", "text": "(You settle into your seat, next to a stranger.)", "text_fr": "(Vous vous installez à votre siège, à côté d''un inconnu.)", "choices": [{"text": "(Say a friendly hello to your neighbor.)", "text_fr": "(Dis un bonjour amical à ton voisin.)", "next": "n4"}]}, "n2c": {"speaker": "flight_attendant", "text": "Let me check again... yes, there''s a window seat available in row 22.", "text_fr": "Laissez-moi vérifier encore... oui, il y a un siège hublot disponible en rangée 22.", "choices": [{"text": "That''s perfect, thank you so much!", "text_fr": "C''est parfait, merci beaucoup !", "next": "n3"}]}, "n3": {"speaker": "flight_attendant", "text": "Great, here''s your new seat assignment.", "text_fr": "Super, voici votre nouvelle attribution de siège.", "choices": [{"text": "Thank you for your help.", "text_fr": "Merci pour votre aide.", "next": "n4"}]}, "n4": {"speaker": "neighbor", "text": "Hi there! Looks like we''re neighbors for this flight.", "text_fr": "Salut ! On dirait qu''on est voisins pour ce vol.", "choices": [{"text": "Hi! Yes, looks like it. Where are you headed?", "text_fr": "Salut ! Oui, on dirait. Vous allez où ?", "next": "n5"}, {"text": "Hello! Nice to meet you. Business or pleasure trip?", "text_fr": "Bonjour ! Ravi de vous rencontrer. Voyage d''affaires ou d''agrément ?", "next": "n5b"}]}, "n5": {"speaker": "neighbor", "text": "Heading home actually, after a work conference. You?", "text_fr": "Je rentre chez moi en fait, après une conférence de travail. Et vous ?", "choices": [{"text": "Visiting family for a few weeks, first time in a while.", "text_fr": "Je rends visite à ma famille pendant quelques semaines, première fois depuis un moment.", "next": "n6"}, {"text": "Just a vacation, I''ve been looking forward to this trip.", "text_fr": "Juste des vacances, j''attends ce voyage avec impatience.", "next": "n6"}]}, "n5b": {"speaker": "neighbor", "text": "Pleasure, definitely — long overdue vacation!", "text_fr": "Agrément, définitivement — des vacances qui se faisaient attendre !", "choices": [{"text": "That sounds well deserved! Where are you headed?", "text_fr": "Ça a l''air bien mérité ! Vous allez où ?", "next": "n6"}]}, "n6": {"speaker": "neighbor", "text": "That''s nice. So, are you a nervous flyer, or do you enjoy it?", "text_fr": "C''est sympa. Alors, vous êtes du genre nerveux en avion, ou vous aimez ça ?", "choices": [{"text": "Honestly, a bit nervous during takeoff, but I''m usually fine.", "text_fr": "Honnêtement, un peu nerveux au décollage, mais généralement ça va.", "next": "n7"}, {"text": "I actually love flying, the whole experience fascinates me.", "text_fr": "J''adore en fait voler, toute l''expérience me fascine.", "next": "n7"}]}, "n7": {"speaker": "neighbor", "text": "(Chats comfortably through most of the flight, sharing stories.)", "text_fr": "(Discute confortablement pendant la majeure partie du vol, en partageant des histoires.)", "choices": [{"text": "This conversation really made the flight go by faster.", "text_fr": "Cette conversation a vraiment fait passer le vol plus vite.", "next": "n8"}, {"text": "(Eventually put on headphones to rest, politely.)", "text_fr": "(Finit par mettre des écouteurs pour se reposer, poliment.)", "next": "n8b"}]}, "n8": {"speaker": "neighbor", "text": "Agreed! It''s rare to have such a pleasant conversation on a flight.", "text_fr": "D''accord ! C''est rare d''avoir une conversation si agréable en avion.", "choices": [{"text": "Definitely, safe travels wherever you''re headed next!", "text_fr": "Carrément, bon voyage où que vous alliez ensuite !", "next": "end_pleasant"}]}, "n8b": {"speaker": "neighbor", "text": "Of course, go ahead and rest — it was nice chatting though!", "text_fr": "Bien sûr, allez-y reposez-vous — c''était sympa de discuter par contre !", "choices": [{"text": "It really was, enjoy the rest of your flight.", "text_fr": "C''était vraiment sympa, profitez du reste du vol.", "next": "end_pleasant"}]}, "end_pleasant": {"speaker": "neighbor", "text": "You too! Safe travels.", "text_fr": "Vous aussi ! Bon voyage.", "end": true, "ending_label": "Un vol agréable et une belle rencontre ✈️😊"}}}'::jsonb, is_playable = true
where title = 'Demander un changement de siège et discuter avec son voisin'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
